mapper.select:
select p.user_id userId, p.lat lat, p.lng lng, p.uptime `time`, d.nickname `nickname`, d.avatar avatar, d.role role, d.group `group`, d.con con from corgi_user_follow f left join corgi_user_position p on a.user_id = p.user_id left join corgi_user_detail d on d.user_id = p.user_id where f.user_id = #{userId}
order by f.id desc
order by p.uptime desc
order by st_distance_sphere(point(#{lng},#{lat}),p.pt)
limit #{start},#{size}
